"""Render docs/03_results.md directly from results/*.json (no hand-copied numbers)."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
r1 = json.load(open(ROOT / "results/test1_synthetic.json"))
r2 = json.load(open(ROOT / "results/test2_k562.json"))
r3 = json.load(open(ROOT / "results/test3_cell_state_mu.json"))
f3 = lambda x: f"{x:.3f}"
esc = lambda x: str(x).replace("|", "\\|")
L = ["# Results (numeric)", "",
     "Generated by `scripts/make_results_md.py` from `results/*.json`. AUPRC× = AUPRC ÷ base rate (1.00 = random).", ""]

# ---------- Test 1 ----------
a = r1["aggregate_mean_sd"]; c = r1["config"]
L += ["## Test 1 — Synthetic sanity check", "",
      f"Config: genes={c['G']}, TFs={c['T']}, conditions={c['C']}, strong targets/TF={c['N_STRONG']}, "
      f"weak-cluster targets/TF={c['N_WEAK']} ({c['K_WEAK']} sites each), noise σ={c['SIGMA']}, seeds={c['seeds']}. "
      "Values are mean ± sd over seeds.", "",
      "| Method | AUROC (all) | AUPRC× (all) | AUROC strong vs none | AUROC weak vs none | Recall strong @K | Recall weak @K |",
      "|---|---|---|---|---|---|---|"]
for n, v in a.items():
    if not isinstance(v, dict):
        continue
    L.append(f"| {esc(n)} | " + " | ".join(f"{v[k][0]:.3f} ± {v[k][1]:.3f}" for k in
             ["AUROC_all", "AUPRC_ratio_all", "AUROC_strong_vs_none", "AUROC_weak_vs_none",
              "recall_strong_at_topK", "recall_weak_at_topK"]) + " |")
L += ["", "| Quantity | Value (mean ± sd) |", "|---|---|"]
for k, lab in [("mu_recovery_spearman_median", "μ recovery, Spearman(μ̂, μ_true) per TF, median (after sign orientation)"),
               ("mu_recovery_abs_spearman_median", "μ recovery, |Spearman| per TF, median (no orientation)"),
               ("w_sign_accuracy_raw", "w sign accuracy, raw"),
               ("w_sign_accuracy", "w sign accuracy, after orientation with TF proxy"),
               ("proxy_vs_mu_spearman_median", "Noisy TF proxy vs μ_true, Spearman median (baseline input quality)"),
               ("weak_targets_with_zero_hits_frac", "Fraction of weak-cluster targets with 0 thresholded hits"),
               ("fit_seconds", "BOND fit time per seed (s)")]:
    L.append(f"| {esc(lab)} | {a[k][0]:.3f} ± {a[k][1]:.3f} |")

# ---------- Test 2 ----------
L += ["", "## Test 2 — K562 binding (ChIP-seq) and function (Perturb-seq)", "",
      f"Genes={r2['n_genes']} (1-kb upstream promoters of Perturb-seq-measured genes); TFs evaluated for binding={r2['n_tfs_binding_eval']}; "
      f"median fraction of promoters ChIP-bound per TF={f3(r2['chip_bound_frac_median'])}. Per-TF metrics averaged over TFs.", "",
      "### 2a. Predicting ChIP-seq binding", "",
      "| Score | AUROC mean | AUROC median | AUPRC× mean | AUPRC× median | n TFs |", "|---|---|---|---|---|---|"]
for s, v in r2["binding"].items():
    L.append(f"| {esc(s)} | {f3(v['AUROC']['mean'])} | {f3(v['AUROC']['median'])} | {f3(v['AUPRC_ratio']['mean'])} | {f3(v['AUPRC_ratio']['median'])} | {v['AUROC']['n']} |")
L += ["", "| Head-to-head (fraction of TFs where first beats second, AUPRC) | Value |", "|---|---|"]
for k, v in r2["binding_win_frac"].items():
    L.append(f"| {esc(k)} | {f3(v)} |")
L += ["", "### 2b. Weak-site test (promoters with zero thresholded motif hits)", "",
      "| Score (restricted set) | AUROC mean | AUROC median | n TFs |", "|---|---|---|---|"]
for k, v in r2["weak_sites_AUROC"].items():
    L.append(f"| {esc(k)} | {f3(v['mean'])} | {f3(v['median'])} | {v['n']} |")
L += ["", "| Quantity | Value |", "|---|---|",
      f"| Median fraction of promoters with zero hits per TF | {f3(r2['zero_hit_gene_frac_median'])} |",
      f"| Median fraction of ChIP-bound promoters with zero hits per TF | {f3(r2['bound_genes_with_zero_hits_frac_median'])} |",
      f"| Fraction of promoters overlapping a K562 ATAC peak | {f3(r2['promoters_overlapping_ATAC_peak_frac'])} |"]
L += ["", "### 2c. Held-out TFs (5 TF folds)", "",
      "| Score | AUROC mean | AUROC median | AUPRC× mean | AUPRC× median |", "|---|---|---|---|---|"]
for k, v in r2["heldout_TF"].items():
    if isinstance(v, dict):
        L.append(f"| {esc(k)} | {f3(v['AUROC']['mean'])} | {f3(v['AUROC']['median'])} | {f3(v['AUPRC_ratio']['mean'])} | {f3(v['AUPRC_ratio']['median'])} |")
L.append(f"| Fraction of TFs where adding occupancy to LR[hub+acc] raises AUPRC | {f3(r2['heldout_TF']['occupancy_adds_over_hub_frac_TFs(AUPRC)'])} | | | |")
fn = r2["function"]
L += ["", "### 2d. Predicting knockdown response (Perturb-seq, |z| ≥ " + str(fn["z_threshold"]) + ")", "",
      f"TFs with JASPAR motif + K562 ChIP + knockdown (fold_expr < 0.85) + ≥20 responsive genes: {fn['n_tfs']} ({', '.join(fn['tfs'])}).", "",
      "| Score | AUROC mean | AUROC median | AUPRC× mean | AUPRC× median |", "|---|---|---|---|---|"]
for s, v in fn["scores"].items():
    L.append(f"| {esc(s)} | {f3(v['AUROC']['mean'])} | {f3(v['AUROC']['median'])} | {f3(v['AUPRC_ratio']['mean'])} | {f3(v['AUPRC_ratio']['median'])} |")
L += ["", "| Binding-vs-function overlap (median over TFs) | Value |", "|---|---|"]
for k, v in fn["binding_function_overlap_median"].items():
    L.append(f"| {esc(k)} | {f3(v)} |")
L += ["", "Direct-edge proxy label = ChIP-bound AND responsive:", "",
      "| Score | AUROC mean | AUPRC× mean | n TFs |", "|---|---|---|---|"]
for s, v in fn["direct_proxy(bound&responsive)"].items():
    L.append(f"| {esc(s)} | {f3(v['AUROC']['mean'])} | {f3(v['AUPRC_ratio']['mean'])} | {v['AUROC']['n']} |")

# ---------- Test 3 ----------
L += ["", "## Test 3 — Cell-state μ (K562 vs HepG2)", "",
      f"Genes={r3['n_genes']} (held-out test genes={r3['n_test_genes']}); TFs={r3['n_tfs']} (ChIP in both lines + JASPAR); sparse sites={r3['n_sites']}.", "",
      "| Model | R² test (log TPM) | R² train | R² test (Δ HepG2−K562) | Converged | Fit time (s) |", "|---|---|---|---|---|---|"]
L.append(f"| ACC_only (linear) | {f3(r3['ACC_only']['R2_test_y'])} | – | {f3(r3['ACC_only']['R2_test_delta_y'])} | – | – |")
for k in ["OCC_mu_fixed", "OCC_mu_shared", "OCC_mu_state", "OCC_mu_state_lam1e-6"]:
    v = r3[k]
    L.append(f"| {esc(k)} | {f3(v['R2_test_y'])} | {f3(v['R2_train_y'])} | {f3(v['R2_test_delta_y'])} | {v['converged']} | {v['fit_seconds']:.0f} |")
L += ["", f"Reference ceiling — Spearman(ChIP peak-count ratio, TF mRNA ratio) = {f3(r3['reference: ChIP_peak_ratio vs TF_mRNA_ratio (spearman)'])}", ""]
for fname in ["state", "state_lam1e-6"]:
    V = r3[f"delta_mu_validation[{fname}]"]; Sm = r3[f"delta_mu_summary[{fname}]"]
    L += [f"### Δμ validation — fit `{fname}`", "",
          "| Independent proxy | Spearman (all TFs) | Permutation p (two-sided, 1000) | Spearman (top half by abs(w)) |", "|---|---|---|---|"]
    for k, v in V.items():
        L.append(f"| {esc(k)} | {f3(v['spearman_all_TFs'])} | {f3(v['perm_p_two_sided'])} | {f3(v['spearman_top_half_|w|'])} |")
    L += ["", "| Δμ summary | Value |", "|---|---|"] + [f"| {esc(k)} | {f3(v)} |" for k, v in Sm.items()]
    L += ["", "| Marker TF | Δμ (HepG2−K562) | w | TF mRNA log2 ratio |", "|---|---|---|---|"]
    for t, v in r3[f"markers_delta_mu(HepG2-K562)[{fname}]"].items():
        L.append(f"| {t} | {f3(v['delta_mu'])} | {f3(v['w'])} | {f3(v['mRNA_log2ratio'])} |")
    L.append("")
(ROOT / "docs/03_results.md").write_text("\n".join(L) + "\n")
print("wrote", len(L), "lines")

# ---------- ProBound additions ----------
pb = json.load(open(ROOT / "results/test2b_probound_vs_jaspar.json"))
jc = json.load(open(ROOT / "results/test2_k562_jaspar_common.json"))
pc = json.load(open(ROOT / "results/test2_k562_probound_common.json"))
p3 = json.load(open(ROOT / "results/test3_cell_state_mu_probound.json"))
M = ["", "## ProBound free-energy models vs JASPAR PWMs", "",
     f"Common TFs (K562 ChIP + JASPAR + ProBound): {pb['n_tfs_common']}; ProBound model source: "
     + ", ".join(f"{k}={v}" for k, v in pb["probound_model_source_counts"].items())
     + f". Median E_thr (kT): JASPAR={f3(pb['Ethr_median_kT']['jaspar'])}, ProBound={f3(pb['Ethr_median_kT']['probound'])}. "
     f"Median motif width: JASPAR={pb['motif_width_median']['jaspar']:.0f}, ProBound={pb['motif_width_median']['probound']:.0f}.", "",
     "### Binding (ChIP), paired per TF", "",
     "| Score [metric] | JASPAR mean | ProBound mean | JASPAR median | ProBound median | ProBound wins (frac TFs) | Wilcoxon p | n |",
     "|---|---|---|---|---|---|---|---|"]
for k, v in pb["scores"].items():
    M.append(f"| {esc(k)} | {f3(v['JASPAR_mean'])} | {f3(v['ProBound_mean'])} | {f3(v['JASPAR_median'])} | {f3(v['ProBound_median'])} | "
             f"{f3(v['ProBound_wins_frac'])} | {v['wilcoxon_p']:.2g} | {v['n']} |")
M += ["", "### Held-out TFs, common TF set", "",
      "| Score | JASPAR AUROC | ProBound AUROC | JASPAR AUPRC× | ProBound AUPRC× |", "|---|---|---|---|---|"]
for k in jc["heldout_TF"]:
    a, b = jc["heldout_TF"][k], pc["heldout_TF"][k]
    if isinstance(a, dict):
        M.append(f"| {esc(k)} | {f3(a['AUROC']['mean'])} | {f3(b['AUROC']['mean'])} | {f3(a['AUPRC_ratio']['mean'])} | {f3(b['AUPRC_ratio']['mean'])} |")
    else:
        M.append(f"| {esc(k)} | {f3(a)} | {f3(b)} | | |")
M += ["", f"### Function (Perturb-seq), common TF set, n = {pc['function']['n_tfs']} TFs ({', '.join(pc['function']['tfs'])})", "",
      "| Score | JASPAR AUROC | ProBound AUROC | JASPAR AUPRC× | ProBound AUPRC× |", "|---|---|---|---|---|"]
for k in pc["function"]["scores"]:
    a, b = jc["function"]["scores"][k], pc["function"]["scores"][k]
    M.append(f"| {esc(k)} | {f3(a['AUROC']['mean'])} | {f3(b['AUROC']['mean'])} | {f3(a['AUPRC_ratio']['mean'])} | {f3(b['AUPRC_ratio']['mean'])} |")
M += ["", f"### Test 3 rerun with ProBound energies (TFs = {p3['n_tfs']}, sparse sites = {p3['n_sites']})", "",
      "| Model | R² test (log TPM) | R² train | R² test (Δ HepG2−K562) | Converged | Fit time (s) |", "|---|---|---|---|---|---|",
      f"| ACC_only (linear) | {f3(p3['ACC_only']['R2_test_y'])} | – | {f3(p3['ACC_only']['R2_test_delta_y'])} | – | – |"]
for k in ["OCC_mu_fixed", "OCC_mu_shared", "OCC_mu_state"]:
    v = p3[k]
    M.append(f"| {k} | {f3(v['R2_test_y'])} | {f3(v['R2_train_y'])} | {f3(v['R2_test_delta_y'])} | {v['converged']} | {v['fit_seconds']:.0f} |")
M += ["", f"Reference — Spearman(ChIP peak-count ratio, TF mRNA ratio) on these TFs = {f3(p3['reference: ChIP_peak_ratio vs TF_mRNA_ratio (spearman)'])}", "",
      "| Independent proxy | Spearman (all TFs) | Permutation p | Spearman (top half by abs(w)) |", "|---|---|---|---|"]
for k, v in p3["delta_mu_validation[state]"].items():
    M.append(f"| {k} | {f3(v['spearman_all_TFs'])} | {f3(v['perm_p_two_sided'])} | {f3(v['spearman_top_half_|w|'])} |")
M += ["", "| Δμ summary (ProBound, state) | Value |", "|---|---|"] + \
     [f"| {esc(k)} | {f3(v)} |" for k, v in p3["delta_mu_summary[state]"].items()]
with open(ROOT / "docs/03_results.md", "a") as fh:
    fh.write("\n".join(M) + "\n")
print("appended ProBound sections")
